// main.go - MPM Database & Ingestion Layer
package main

import (
    "crypto/sha256"
    "database/sql"
    "encoding/hex"
    "fmt"
    "io"
    "os"
    "path/filepath"
    "strings"
    "time"

    "github.com/fsnotify/fsnotify"
    _ "github.com/mattn/go-sqlite3"
)

// Database schema and ingestion implementation
func main() {
    // Initialize database
    db, err := initDatabase()
    if err != nil {
        panic(fmt.Sprintf("Failed to initialize database: %v", err))
    }
    defer db.Close()

    // Load toxic phrases
    toxicPhrases, err := loadToxicPhrases("toxicphrases.txt")
    if err != nil {
        fmt.Printf("Warning: Could not load toxic phrases: %v\n", err)
    }

    // Start file watchers
    startWatchers(db, toxicPhrases)
}

// ==================== DATABASE SCHEMA ====================
func initDatabase() (*sql.DB, error) {
    db, err := sql.Open("sqlite3", "mpm_memory.db")
    if err != nil {
        return nil, fmt.Errorf("failed to open database: %w", err)
    }

    // Enable foreign keys
    _, err = db.Exec("PRAGMA foreign_keys = ON;")
    if err != nil {
        return nil, fmt.Errorf("failed to enable foreign keys: %w", err)
    }

    // Create tables
    err = createTables(db)
    if err != nil {
        return nil, fmt.Errorf("failed to create tables: %w", err)
    }

    // Create FTS5 virtual tables and triggers
    err = createFTSAndTriggers(db)
    if err != nil {
        return nil, fmt.Errorf("failed to create FTS tables: %w", err)
    }

    return db, nil
}

func createTables(db *sql.DB) error {
    // sessions table - stores individual session entries
    sessionsSQL := `
    CREATE TABLE IF NOT EXISTS sessions (
        id TEXT PRIMARY KEY,
        session_id TEXT NOT NULL,
        content TEXT NOT NULL,
        content_hash TEXT UNIQUE NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        source_path TEXT,
        metadata JSON
    );
    `

    // topics table - for organizing memories into categories
    topicsSQL := `
    CREATE TABLE IF NOT EXISTS topics (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL UNIQUE,
        description TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    `

    // topic_memberships table - many-to-many relationship
    topicMembershipsSQL := `
    CREATE TABLE IF NOT EXISTS topic_memberships (
        session_id TEXT NOT NULL,
        topic_id TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (session_id, topic_id),
        FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
        FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
    );
    `

    // memories table - consolidated memory storage
    memoriesSQL := `
    CREATE TABLE IF NOT EXISTS memories (
        id TEXT PRIMARY KEY,
        collection TEXT NOT NULL,
        content TEXT NOT NULL,
        session_id TEXT,
        tags JSON,
        metadata JSON,
        embedding JSON,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    `

    // Execute table creation
    for _, sql := range []string{sessionsSQL, topicsSQL, topicMembershipsSQL, memoriesSQL} {
        _, err := db.Exec(sql)
        if err != nil {
            return fmt.Errorf("failed to create table: %w\nSQL: %s", err, sql)
        }
    }

    return nil
}

func createFTSAndTriggers(db *sql.DB) error {
    // Create FTS5 virtual tables for full-text search
    ftsSessionsSQL := `
    CREATE VIRTUAL TABLE IF NOT EXISTS sessions_fts USING fts5(
        content,
        session_id,
        content_hash UNINDEXED,
        tokenize='porter'
    );
    `

    ftsMemoriesSQL := `
    CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(
        content,
        collection,
        session_id UNINDEXED,
        tags UNINDEXED,
        tokenize='porter'
    );
    `

    // Create triggers to automatically update FTS tables
    triggersSQL := []string{
        // Sessions triggers
        `CREATE TRIGGER IF NOT EXISTS sessions_ai AFTER INSERT ON sessions
         BEGIN
             INSERT INTO sessions_fts(rowid, content, session_id, content_hash)
             VALUES (new.rowid, new.content, new.session_id, new.content_hash);
         END;`,

        `CREATE TRIGGER IF NOT EXISTS sessions_ad AFTER DELETE ON sessions
         BEGIN
             DELETE FROM sessions_fts WHERE rowid = old.rowid;
         END;`,

        `CREATE TRIGGER IF NOT EXISTS sessions_au AFTER UPDATE ON sessions
         BEGIN
             DELETE FROM sessions_fts WHERE rowid = old.rowid;
             INSERT INTO sessions_fts(rowid, content, session_id, content_hash)
             VALUES (new.rowid, new.content, new.session_id, new.content_hash);
         END;`,

        // Memories triggers
        `CREATE TRIGGER IF NOT EXISTS memories_ai AFTER INSERT ON memories
         BEGIN
             INSERT INTO memories_fts(rowid, content, collection, session_id, tags)
             VALUES (new.rowid, new.content, new.collection, new.session_id, new.tags);
         END;`,

        `CREATE TRIGGER IF NOT EXISTS memories_ad AFTER DELETE ON memories
         BEGIN
             DELETE FROM memories_fts WHERE rowid = old.rowid;
         END;`,

        `CREATE TRIGGER IF NOT EXISTS memories_au AFTER UPDATE ON memories
         BEGIN
             DELETE FROM memories_fts WHERE rowid = old.rowid;
             INSERT INTO memories_fts(rowid, content, collection, session_id, tags)
             VALUES (new.rowid, new.content, new.collection, new.session_id, new.tags);
         END;`,
    }

    // Execute FTS table creation
    for _, sql := range []string{ftsSessionsSQL, ftsMemoriesSQL} {
        _, err := db.Exec(sql)
        if err != nil {
            return fmt.Errorf("failed to create FTS table: %w\nSQL: %s", err, sql)
        }
    }

    // Execute trigger creation
    for _, sql := range triggersSQL {
        _, err := db.Exec(sql)
        if err != nil {
            return fmt.Errorf("failed to create trigger: %w\nSQL: %s", err, sql)
        }
    }

    return nil
}

// ==================== SECURITY MIDDLEWARE ====================
func loadToxicPhrases(path string) ([]string, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, fmt.Errorf("failed to read toxic phrases file: %w", err)
    }

    lines := strings.Split(string(data), "\n")
    var phrases []string
    for _, line := range lines {
        trimmed := strings.TrimSpace(line)
        if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
            phrases = append(phrases, strings.ToLower(trimmed))
        }
    }

    return phrases, nil
}

func checkToxicContent(content string, toxicPhrases []string) bool {
    lowerContent := strings.ToLower(content)
    for _, phrase := range toxicPhrases {
        if strings.Contains(lowerContent, phrase) {
            return true
        }
    }
    return false
}

func logSecurityAlert(filePath, contentHash string) error {
    logEntry := fmt.Sprintf("[%s] SECURITY ALERT: Toxic content detected in file %s (hash: %s)\n",
        time.Now().Format(time.RFC3339), filePath, contentHash)

    f, err := os.OpenFile("security.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
    if err != nil {
        return fmt.Errorf("failed to open security log: %w", err)
    }
    defer f.Close()

    _, err = f.WriteString(logEntry)
    return err
}

// ==================== INGESTION LOGIC ====================
func calculateContentHash(content string) string {
    hash := sha256.Sum256([]byte(content))
    return hex.EncodeToString(hash[:])
}

func processFile(filePath string, db *sql.DB, toxicPhrases []string) error {
    // Read file content
    content, err := os.ReadFile(filePath)
    if err != nil {
        return fmt.Errorf("failed to read file %s: %w", filePath, err)
    }

    contentStr := string(content)
    contentHash := calculateContentHash(contentStr)

    // Check for toxic content
    if len(toxicPhrases) > 0 && checkToxicContent(contentStr, toxicPhrases) {
        // Log security alert
        logSecurityAlert(filePath, contentHash)

        // Delete the file
        if err := os.Remove(filePath); err != nil {
            return fmt.Errorf("failed to delete toxic file %s: %w", filePath, err)
        }

        fmt.Printf("Security alert: Toxic content detected and file deleted: %s\n", filePath)
        return nil // Stop processing this file
    }

    // Check for duplicates
    var existingID string
    err = db.QueryRow("SELECT id FROM sessions WHERE content_hash = ?", contentHash).Scan(&existingID)
    if err == nil {
        // Duplicate found - delete the file
        fmt.Printf("Duplicate detected (hash: %s), deleting file: %s\n", contentHash, filePath)
        return os.Remove(filePath)
    } else if err != sql.ErrNoRows {
        return fmt.Errorf("failed to check for duplicates: %w", err)
    }

    // Extract session ID from filename or path
    filename := filepath.Base(filePath)
    sessionID := strings.TrimSuffix(filename, filepath.Ext(filename))

    // Insert into database
    _, err = db.Exec(`
        INSERT INTO sessions (id, session_id, content, content_hash, source_path)
        VALUES (?, ?, ?, ?, ?)
    `, contentHash, sessionID, contentStr, contentHash, filePath)

    if err != nil {
        return fmt.Errorf("failed to insert session: %w", err)
    }

    // Always delete the file after successful insertion
    if err := os.Remove(filePath); err != nil {
        return fmt.Errorf("failed to delete processed file %s: %w", filePath, err)
    }

    fmt.Printf("Successfully ingested: %s (hash: %s)\n", filePath, contentHash)
    return nil
}

// ==================== FILE WATCHER ====================
func startWatchers(db *sql.DB, toxicPhrases []string) {
    watcher, err := fsnotify.NewWatcher()
    if err != nil {
        panic(fmt.Sprintf("Failed to create watcher: %v", err))
    }
    defer watcher.Close()

    // Watch directories
    dirs := []string{"sessions", "memory"}
    for _, dir := range dirs {
        // Create directory if it doesn't exist
        if err := os.MkdirAll(dir, 0755); err != nil {
            fmt.Printf("Warning: Failed to create directory %s: %v\n", dir, err)
            continue
        }

        if err := watcher.Add(dir); err != nil {
            fmt.Printf("Warning: Failed to watch directory %s: %v\n", dir, err)
        } else {
            fmt.Printf("Watching directory: %s\n", dir)
        }
    }

    // Process existing files on startup
    for _, dir := range dirs {
        files, err := filepath.Glob(filepath.Join(dir, "*.md"))
        if err != nil {
            fmt.Printf("Warning: Failed to list files in %s: %v\n", dir, err)
            continue
        }

        for _, file := range files {
            if err := processFile(file, db, toxicPhrases); err != nil {
                fmt.Printf("Error processing existing file %s: %v\n", file, err)
            }
        }
    }

    // Main event loop
    for {
        select {
        case event, ok := <-watcher.Events:
            if !ok {
                return
            }

            // Only process .md files on write/create
            if (event.Op&fsnotify.Write == fsnotify.Write || event.Op&fsnotify.Create == fsnotify.Create) &&
               strings.HasSuffix(event.Name, ".md") {

                // Small delay to ensure file is fully written
                time.Sleep(100 * time.Millisecond)

                if err := processFile(event.Name, db, toxicPhrases); err != nil {
                    fmt.Printf("Error processing file %s: %v\n", event.Name, err)
                }
            }

        case err, ok := <-watcher.Errors:
            if !ok {
                return
            }
            fmt.Printf("Watcher error: %v\n", err)
        }
    }
}

// ==================== HELPER FUNCTIONS ====================
func ensureEmptyDirectories() {
    dirs := []string{"sessions", "memory"}
    for _, dir := range dirs {
        // Read directory
        entries, err := os.ReadDir(dir)
        if err != nil {
            if os.IsNotExist(err) {
                // Create directory
                os.MkdirAll(dir, 0755)
            }
            continue
        }

        // Delete any remaining files
        for _, entry := range entries {
            if !entry.IsDir() {
                filePath := filepath.Join(dir, entry.Name())
                os.Remove(filePath)
                fmt.Printf("Cleaned up orphaned file: %s\n", filePath)
            }
        }
    }
}
