	BEGIN
		INSERT INTO memories_fts(rowid, content, collection, session_id, tags)
		VALUES (new.rowid, new.content, new.collection, new.session_id, new.tags);
	END;

	CREATE TRIGGER IF NOT EXISTS memories_ad AFTER DELETE ON memories
	BEGIN
		DELETE FROM memories_fts WHERE rowid = old.rowid;
	END;

	CREATE TRIGGER IF NOT EXISTS memories_au AFTER UPDATE ON memories
	BEGIN
		DELETE FROM memories_fts WHERE rowid = old.rowid;
		INSERT INTO memories_fts(rowid, content, collection, session_id, tags)
		VALUES (new.rowid, new.content, new.collection, new.session_id, new.tags);
	END;
	`

	// Topics triggers
	topicsTriggers := `
	CREATE TRIGGER IF NOT EXISTS topics_ai AFTER INSERT ON topics
	BEGIN
		INSERT INTO topics_fts(rowid, name, description)
		VALUES (new.rowid, new.name, new.description);
	END;

	CREATE TRIGGER IF NOT EXISTS topics_ad AFTER DELETE ON topics
	BEGIN
		DELETE FROM topics_fts WHERE rowid = old.rowid;
	END;

	CREATE TRIGGER IF NOT EXISTS topics_au AFTER UPDATE ON topics
	BEGIN
		DELETE FROM topics_fts WHERE rowid = old.rowid;
		INSERT INTO topics_fts(rowid, name, description)
		VALUES (new.rowid, new.name, new.description);
	END;
	`

	// Update triggers for configuration tables (no FTS)
	configTriggers := `
	CREATE TRIGGER IF NOT EXISTS modes_au AFTER UPDATE ON modes
	BEGIN
		UPDATE modes SET updated_at = CURRENT_TIMESTAMP WHERE id = new.id;
	END;

	CREATE TRIGGER IF NOT EXISTS personas_au AFTER UPDATE ON personas
	BEGIN
		UPDATE personas SET updated_at = CURRENT_TIMESTAMP WHERE id = new.id;
	END;
	`

	// Execute all SQL statements
	sqlStatements := []string{
		// Cognitive tables
		sessionsSQL,
		topicsSQL,
		topicMembershipsSQL,
		memoriesSQL,

		// Configuration tables
		modesSQL,
		personasSQL,

		// FTS5 tables
		sessionsFTS,
