		topicsFTS,

		// Triggers
		sessionsTriggers,
		memoriesTriggers,
		topicsTriggers,
		configTriggers,
	}

	for _, sql := range sqlStatements {
		if _, err := dm.DB.Exec(sql); err != nil {
			return fmt.Errorf("failed to execute SQL: %w\nSQL: %s", err, sql)
		}
	}

