// VectorSearch performs vector similarity search on cognitive tables
func (dm *DatabaseManager) VectorSearch(tier string, queryEmbedding []float32, limit int) ([]map[string]interface{}, error) {
	if limit <= 0 {
		limit = 10
	}

	// Determine which table to search based on tier
	var tableName string
	switch tier {
	case "sessions":
		tableName = "sessions"
	case "memories":
		tableName = "memories"
	case "topics":
		tableName = "topics"
	default:
		return nil, fmt.Errorf("unsupported tier for vector search: %s", tier)
	}

	// Convert embedding to JSON for SQLite JSON functions
	queryEmbeddingJSON, err := json.Marshal(queryEmbedding)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal query embedding: %w", err)
	}

	// SQLite doesn't have built-in vector operations, so we use a simple
	// cosine similarity approximation with JSON arrays
	// Note: For production use, consider using a dedicated vector database
	query := fmt.Sprintf(`
		SELECT id, content, 
		       json_extract(embedding, '$') as embedding_json,
		       created_at
		FROM %s
		WHERE embedding IS NOT NULL
		ORDER BY (
			-- Simple cosine similarity approximation
			SELECT SUM(a * b) / 
			       (SQRT(SUM(a * a)) * SQRT(SUM(b * b)))
			FROM json_each(json_extract(embedding, '$')) as e1,
			     json_each(?) as e2
			WHERE e1.key = e2.key
		) DESC
		LIMIT ?
	`, tableName)

	rows, err := dm.DB.Query(query, string(queryEmbeddingJSON), limit)
	if err != nil {
		return nil, fmt.Errorf("failed to perform vector search: %w", err)
	}
	defer rows.Close()

	var results []map[string]interface{}
	for rows.Next() {
		var id, content, embeddingJSON string
		var createdAt time.Time

		if err := rows.Scan(&id, &content, &embeddingJSON, &createdAt); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Parse embedding
		var embedding []float32
		if embeddingJSON != "" {
			if err := json.Unmarshal([]byte(embeddingJSON), &embedding); err != nil {
				embedding = nil
			}
		}

		results = append(results, map[string]interface{}{
			"id":        id,
			"content":   content,
			"embedding": embedding,
			"created_at": createdAt,
		})
	}

	return results, nil
}

