// WipeRecord securely deletes a record from cognitive tables
func (dm *DatabaseManager) WipeRecord(tier, id string) error {
	// Only allow wiping from cognitive tables
	var tableName string
	switch tier {
	case "sessions", "memories", "topics":
		tableName = tier
	default:
		return fmt.Errorf("cannot wipe from tier: %s (only sessions, memories, topics allowed)", tier)
	}

	// Begin transaction
	tx, err := dm.DB.Begin()
	if err != nil {
		return fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer tx.Rollback() // Will be ignored if committed

	// Perform hard DELETE
	_, err = tx.Exec(fmt.Sprintf("DELETE FROM %s WHERE id = ?", tableName), id)
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	// Commit transaction
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("failed to commit transaction: %w", err)
	}

	// Perform VACUUM to reclaim space and securely erase
	// Note: VACUUM can be slow on large databases
	_, err = dm.DB.Exec("VACUUM")
	if err != nil {
		return fmt.Errorf("failed to vacuum database: %w", err)
	}

	return nil
}

