// GenerateID generates a unique ID using SHA256 hash of timestamp
func GenerateID() string {
	timestamp := time.Now().UnixNano()
	hash := sha256.Sum256([]byte(fmt.Sprintf("%d-%d", timestamp, time.Now().UnixNano())))
	return hex.EncodeToString(hash[:])[:16] // 16 chars for readability
}

// GetCurrentTime returns current time in RFC3339 format
func GetCurrentTime() string {
	return time.Now().UTC().Format(time.RFC3339)
}

// MarshalJSON safely marshals data to JSON
func MarshalJSON(v interface{}) (string, error) {
	data, err := json.Marshal(v)
	return string(data), err
}

// UnmarshalJSON safely unmarshals JSON data
func UnmarshalJSON(data string, v interface{}) error {
	return json.Unmarshal([]byte(data), v)
}

// EscapeSQL escapes SQL identifiers
func EscapeSQL(s string) string {
	return strings.ReplaceAll(s, "\"", "\"\"")
}
