			fmt.Printf("%d. %s: %s\n", count, name, content)
		}
		if count == 0 {
			fmt.Println("No personas found.")
		}

	default:
		fmt.Printf("Unknown persona command: %s\n", subcmd)
		fmt.Println("Use: save, get, list")
	}
}

// cmdStatus shows database status
func cmdStatus(dbManager *internal.DatabaseManager, args []string) {
